 36	        final StringBuilder buf = new StringBuilder("Missing required option");
 37	        buf.append(missingOptions.size() == 1 ? "" : "s");
 38	        buf.append(": ");
 39	
 40	        final Iterator<?> it = missingOptions.iterator();
 41	        while (it.hasNext()) {
 42	            buf.append(it.next());
 43	            if (it.hasNext()) {
 44	                buf.append(", ");
 45	            }
 46	        }
 47	
 48	        return buf.toString();
 49	    }
